style.css:
@-moz-document domain("lichess.org") {
/* 1. Reset sprite Lichess */
    cg-board piece {
        background-image: none !important;
    }

    piece {
        background-size: contain !important;
        background-repeat: no-repeat !important;
        background-position: center !important;
        opacity: 1 !important;
    }

    /* Pezzi Neri */
    piece.king.black { background-image: url('https://raw.githubusercontent.com/sharechess/sharechess/refs/heads/main/public/pieces/oldstyle/bK.svg') !important; }
    piece.queen.black { background-image: url('https://raw.githubusercontent.com/sharechess/sharechess/refs/heads/main/public/pieces/oldstyle/bQ.svg') !important; }
    piece.rook.black { background-image: url('https://raw.githubusercontent.com/sharechess/sharechess/refs/heads/main/public/pieces/oldstyle/bR.svg') !important; }
    piece.bishop.black { background-image: url('https://raw.githubusercontent.com/sharechess/sharechess/refs/heads/main/public/pieces/oldstyle/bB.svg') !important; }
    piece.knight.black { background-image: url('https://raw.githubusercontent.com/sharechess/sharechess/refs/heads/main/public/pieces/oldstyle/bN.svg') !important; }
    piece.pawn.black { background-image: url('https://raw.githubusercontent.com/sharechess/sharechess/refs/heads/main/public/pieces/oldstyle/bP.svg') !important; }

    /* Pezzi Bianchi */
    piece.king.white { background-image: url('https://raw.githubusercontent.com/sharechess/sharechess/refs/heads/main/public/pieces/oldstyle/wK.svg') !important; }
    piece.queen.white { background-image: url('https://raw.githubusercontent.com/sharechess/sharechess/refs/heads/main/public/pieces/oldstyle/wQ.svg') !important; }
    piece.rook.white { background-image: url('https://raw.githubusercontent.com/sharechess/sharechess/refs/heads/main/public/pieces/oldstyle/wR.svg') !important; }
    piece.bishop.white { background-image: url('https://raw.githubusercontent.com/sharechess/sharechess/refs/heads/main/public/pieces/oldstyle/wB.svg') !important; }
    piece.knight.white { background-image: url('https://raw.githubusercontent.com/sharechess/sharechess/refs/heads/main/public/pieces/oldstyle/wN.svg') !important; }
    piece.pawn.white { background-image: url('https://raw.githubusercontent.com/sharechess/sharechess/refs/heads/main/public/pieces/oldstyle/wP.svg') !important; }
}
